    "X = df[['CPI', 'Unemployment','Fuel_Price']]  # Predictors\n",
    "y = df['Weekly_Sales']  # What we’re predicting\n",
    "X = sm.add_constant(X)  # Adds a baseline for the model\n",
    "model = sm.OLS(y, X).fit()  # Builds the regression\n",
    "print(model.summary())  # Shows results\n",
    "\n",
    "# Extract coefficients (excluding intercept for clarity)\n",
    "coefs = model.params.drop('const')\n",
    "coefs = coefs.sort_values()\n",
